// build/wf/clean-http-request/javascript.ts
function parseAndFilterHeaders(rawRequest, headersToRemove2, headersToReplace2) {
  const lines = rawRequest.split("\r\n");
  let inHeaderSection = true;
  const filteredHeaders = lines.map((line) => {
    if (inHeaderSection && line.trim() === "") {
      inHeaderSection = false;
    }
    if (inHeaderSection) {
      if (line.includes(":")) {
        const [headerName] = line.split(":");
        const trimmedHeaderName = headerName?.trim() || "";
        if (headersToRemove2.includes(trimmedHeaderName)) {
          return "$REMOVE_ME$";
        } else if (headersToReplace2[trimmedHeaderName]) {
          return `${headerName}: ${headersToReplace2[trimmedHeaderName]}`;
        }
      }
    }
    return line;
  }).filter((line) => line !== "$REMOVE_ME$");
  const filteredRequest = filteredHeaders.join("\r\n");
  return filteredRequest;
}
var headersToRemove = [
  "Sec-Fetch-Mode",
  "Sec-Fetch-Site",
  "Sec-Fetch-Dest",
  "sec-ch-ua-platform",
  "sec-ch-ua",
  "sec-ch-ua-mobile",
  "sec-ch-ua-full-version-list",
  "sec-ch-ua-arch",
  "sec-ch-ua-model",
  "sec-ch-ua-platform-version",
  "Connection",
  "Accept-Encoding",
  "Accept-Language",
  "Content-Length"
];
var headersToReplace = {
  Cookie: "YOUR_COOKIES",
  Authorization: "YOUR_AUTH_TOKEN",
  "X-XSRF-TOKEN": "YOUR_XSRF_TOKEN",
  "XSRF-TOKEN": "YOUR_XSRF_TOKEN",
  "CSRF-TOKEN": "YOUR_CSRF_TOKEN"
};
function run(input, sdk) {
  const parsed = sdk.asString(input);
  return parseAndFilterHeaders(parsed, headersToRemove, headersToReplace);
}
